def clasificar_unidades_y_crear_perfiles(apps, schema_editor):
    Unidad = apps.get_model('webcitt', 'Unidad')
    PerfilLaboratorio = apps.get_model('webcitt', 'PerfilLaboratorio')
    PerfilPlantaPiloto = apps.get_model('webcitt', 'PerfilPlantaPiloto')
    PerfilCentroExperimental = apps.get_model('webcitt', 'PerfilCentroExperimental')
    PerfilObservatorio = apps.get_model('webcitt', 'PerfilObservatorio')
    PerfilPlataforma = apps.get_model('webcitt', 'PerfilPlataformaTecnologica')

    perfiles = {
        'laboratorio_academico': PerfilLaboratorio,
        'planta_piloto': PerfilPlantaPiloto,
        'centro_experimental': PerfilCentroExperimental,
        'observatorio': PerfilObservatorio,
        'plataforma_tecnologica': PerfilPlataforma,
    }
    predeterminadas = {
        'laboratorios': 'laboratorio_academico',
        'plantas_piloto': 'planta_piloto',
        'centro_experimental': 'centro_experimental',
        'observatorios': 'observatorio',
    }

    for unidad in Unidad.objects.all().iterator():
        clasificacion = predeterminadas.get(unidad.dependencia, '')
        identificador = f'{unidad.nombre} {unidad.slug or ""}'.lower()
        if unidad.dependencia == 'laboratorios' and any(
            termino in identificador
            for termino in ('fablab', 'manufactura digital', 'fabricacion digital')
        ):
            clasificacion = 'plataforma_tecnologica'

        Unidad.objects.filter(pk=unidad.pk).update(
            clasificacion_funcional=clasificacion,
        )
        modelo_perfil = perfiles.get(clasificacion)
        if modelo_perfil:
            modelo_perfil.objects.get_or_create(unidad_id=unidad.pk)


def limpiar_clasificaciones_y_perfiles(apps, schema_editor):
    for nombre_modelo in (
        'PerfilLaboratorio',
        'PerfilPlantaPiloto',
        'PerfilCentroExperimental',
        'PerfilObservatorio',
        'PerfilPlataformaTecnologica',
    ):
        apps.get_model('webcitt', nombre_modelo).objects.all().delete()
    apps.get_model('webcitt', 'Unidad').objects.update(clasificacion_funcional='')


